package com.budgetplusplus.data.repository

import android.content.Context
import androidx.room.Room
import androidx.test.core.app.ApplicationProvider
import com.budgetplusplus.core.model.*
import com.budgetplusplus.database.*
import com.budgetplusplus.database.entity.WorkspaceEntity
import java.time.LocalDate
import com.budgetplusplus.domain.repository.*
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.runBlocking
import org.junit.*
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

@RunWith(RobolectricTestRunner::class) @Config(sdk=[35])
class RepositoryIntegrationTest {
 private lateinit var db:BudgetPlusDatabase;private lateinit var accounts:AccountRepository;private lateinit var categories:CategoryRepository;private lateinit var transactions:TransactionRepository
 @Before fun setup()=runBlocking{db=Room.inMemoryDatabaseBuilder(ApplicationProvider.getApplicationContext<Context>(),BudgetPlusDatabase::class.java).allowMainThreadQueries().build();db.openHelper.writableDatabase;createSearchInfrastructure(db.openHelper.writableDatabase);val now=1L;db.openHelper.writableDatabase.execSQL("INSERT INTO workspaces VALUES ('${BudgetPlusDatabase.DEFAULT_WORKSPACE_ID}','Test','PERSONAL','DZD',1,$now,$now,NULL)");accounts=LocalAccountRepository(db,db.accountDao(),db.transactionDao());categories=LocalCategoryRepository(db,db.categoryDao());transactions=LocalTransactionRepository(db,db.transactionDao(),db.accountDao(),db.categoryDao())}
 @After fun close(){db.close()}
 @Test fun `account expense income and transfer journey updates exact balances`()=runBlocking{accounts.create("Cash",AccountType.CASH,10_000);accounts.create("Bank",AccountType.BANK,0);categories.create("Food",CategoryKind.EXPENSE);categories.create("Salary",CategoryKind.INCOME);val a=accounts.observeAccounts().first().associateBy{it.name};val cats=categories.observeCategories().first().associateBy{it.customName};transactions.create(TransactionType.EXPENSE,1_000,a.getValue("Cash").id,null,cats.getValue("Food").id,"Lunch");transactions.create(TransactionType.INCOME,2_000,a.getValue("Cash").id,null,cats.getValue("Salary").id,"Pay");transactions.create(TransactionType.TRANSFER,500,a.getValue("Cash").id,a.getValue("Bank").id,null,"Move");val balances=accounts.observeAccounts().first().associateBy{it.name};assertEquals(10_500,balances.getValue("Cash").currentBalanceMinor);assertEquals(500,balances.getValue("Bank").currentBalanceMinor);assertEquals(3,transactions.observeTransactions().first().size)}
 @Test fun `editing amount account and type atomically recalculates both balances`()=runBlocking{accounts.create("Cash",AccountType.CASH,10_000);accounts.create("Bank",AccountType.BANK,0);categories.create("Food",CategoryKind.EXPENSE);categories.create("Salary",CategoryKind.INCOME);val a=accounts.observeAccounts().first().associateBy{it.name};val cats=categories.observeCategories().first().associateBy{it.customName};transactions.create(TransactionType.EXPENSE,1_000,a.getValue("Cash").id,null,cats.getValue("Food").id,"Old");val id=transactions.observeTransactions().first().single().id;transactions.update(id,TransactionType.INCOME,2_500,a.getValue("Bank").id,null,cats.getValue("Salary").id,"Edited",null,LocalDate.now().toString());val balances=accounts.observeAccounts().first().associateBy{it.name};assertEquals(10_000,balances.getValue("Cash").currentBalanceMinor);assertEquals(2_500,balances.getValue("Bank").currentBalanceMinor);val edited=requireNotNull(transactions.get(id));assertEquals(id,edited.id);assertEquals(TransactionType.INCOME,edited.type);assertEquals("Edited",edited.description);accounts.update(a.getValue("Bank").id,"Main bank",AccountType.SAVINGS,"home","blue","Updated",4);val renamed=accounts.observeAccounts().first().first{it.name=="Main bank"};assertEquals(2_500,renamed.currentBalanceMinor);assertEquals("Updated",renamed.description)}
 @Test fun `selected operation reassignment and safe account deletion preserve totals`()=runBlocking{accounts.create("Source",AccountType.CASH,10_000);accounts.create("Target",AccountType.BANK,0);categories.create("Food",CategoryKind.EXPENSE);val values=accounts.observeAccounts().first().associateBy{it.name};val category=categories.observeCategories().first().single();transactions.create(TransactionType.EXPENSE,1_000,values.getValue("Source").id,null,category.id,"Expense");val operation=transactions.observeTransactions().first().single();accounts.reassignOperations(values.getValue("Source").id,values.getValue("Target").id,setOf(operation.id));var balances=accounts.observeAccounts().first().associateBy{it.name};assertEquals(10_000,balances.getValue("Source").currentBalanceMinor);assertEquals(-1_000,balances.getValue("Target").currentBalanceMinor);accounts.deleteAndReassign(values.getValue("Source").id,values.getValue("Target").id);balances=accounts.observeAccounts().first().associateBy{it.name};assertFalse(balances.containsKey("Source"));assertEquals(9_000,balances.getValue("Target").currentBalanceMinor)}
 @Test fun `deleting a parent safely moves its descendants`()=runBlocking{accounts.create("Parent",AccountType.BANK,1000);val parent=accounts.observeAccounts().first().single();accounts.create("Child",AccountType.CASH,0,parentAccountId=parent.id);accounts.create("Replacement",AccountType.BANK,0);val before=accounts.observeAccounts().first().associateBy{it.name};accounts.deleteAndReassign(parent.id,before.getValue("Replacement").id);val after=accounts.observeAccounts().first().associateBy{it.name};assertFalse(after.containsKey("Parent"));assertEquals(before.getValue("Replacement").id,after.getValue("Child").parentAccountId);assertEquals(1000,after.getValue("Replacement").currentBalanceMinor)}
 @Test fun `account deletion rejects a transfer that would become self transfer`()=runBlocking{accounts.create("Source",AccountType.CASH,0);accounts.create("Target",AccountType.BANK,0);val values=accounts.observeAccounts().first().associateBy{it.name};transactions.create(TransactionType.TRANSFER,500,values.getValue("Source").id,values.getValue("Target").id,null,"Transfer");assertTrue(runCatching{accounts.deleteAndReassign(values.getValue("Source").id,values.getValue("Target").id)}.isFailure);assertTrue(accounts.observeAccounts().first().any{it.name=="Source"})}
 @Test fun `budget repository follows an expense in real time`()=runBlocking{accounts.create("Cash",AccountType.CASH,0);categories.create("Food",CategoryKind.EXPENSE);val account=accounts.observeAccounts().first().single();val category=categories.observeCategories().first().single();val budgets=LocalBudgetRepository(db,db.budgetDao());val today=LocalDate.now();budgets.save(BudgetInput(name="Food",scope=BudgetScope.CATEGORY,categoryId=category.id,amountMinor=10_000,periodType=BudgetPeriodType.CUSTOM,startDate=today.minusDays(1).toString(),endDate=today.plusDays(1).toString()));transactions.create(TransactionType.EXPENSE,2_500,account.id,null,category.id,"Food");assertEquals(2_500,budgets.observeBudgets().first().single().spentMinor)}
}
